import { Composio, SchemaModifier } from '@composio/core';
import * as fs from 'fs';

async function main() {
  const composio = new Composio();
  const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

  // Create a session with the modifier
  const session = await composio.create('zealt-user01', { modifiers: [modifier] });

  // Get tools
  const tools = await session.getTools();

  // Find the modified tool
  const tool = tools.find(t => t.name.toLowerCase().includes('slack') && t.name.toLowerCase().includes('chat_post_message'));

  if (tool) {
    fs.writeFileSync('/home/user/schema.json', JSON.stringify(tool.inputSchema, null, 2));
    console.log('Schema written to /home/user/schema.json');
  } else {
    console.error('Tool not found');
  }
}

main().catch(console.error);

